    await trustRepo(world, repo);
    await addSchedule(world, repo, "Make the failing test pass.", "--name", "nightly", "--every", "5m", "--allow-worktree-write", "--verifier", "node --test", "-e", gw.url, "-m", "m");
    await world.startRunner();
