  policy: JobPolicy;
  verifier: string | null;
  deliverables: string[];
  provider: JobProvider;
  budgets: JobBudgets;
  /** Runs left; null is no limit; 0 disables. */
  remainingRuns: number | null;
  onMissed: ScheduleOnMissed;
  state: ScheduleState;
}

