      console.log(`  last run: ${s.lastFire ? `${s.lastFire.kind === "catch_up" ? "catch-up " : ""}for ${s.lastFire.dueAt}, ${jobSummary(fired)}` : "-"}; last outcome ${s.lastOutcome ?? "-"}`);
